"use client";
import { useState } from "react";
import { Button } from "@fabrials/ui";
import { cn } from "@/lib/utils";

export function safeUrl(value: unknown): string | undefined {
  if (typeof value !== "string") return;
  try {
    const url = new URL(value);
    return ["https:", "http:"].includes(url.protocol) ? url.href : undefined;
  } catch {
    return;
  }
}

function Json({ value }: { value: unknown }) {
  return (
    <pre className="m-0 max-h-96 overflow-auto whitespace-pre-wrap break-words rounded-[var(--fui-radius-md)] border border-[var(--fui-separator)] bg-[var(--fui-code)] p-3.5 font-mono text-xs leading-relaxed">
      {JSON.stringify(value, null, 2) ?? String(value)}
    </pre>
  );
}

function Content({ value }: { value: unknown }) {
  if (!value || typeof value !== "object") return <Json value={value} />;
  const block = value as Record<string, unknown>;
  if (block.type === "text" && typeof block.text === "string")
    return (
      <p className="m-0 whitespace-pre-wrap break-words text-sm leading-relaxed text-foreground">
        {block.text}
      </p>
    );
  if (block.type === "resource_link" && safeUrl(block.uri))
    return (
      <a
        className="text-sm text-[var(--brand-ink)] underline underline-offset-4"
        href={safeUrl(block.uri)}
        target="_blank"
        rel="noopener noreferrer"
      >
        {String(block.name ?? block.uri)}
      </a>
    );
  if (
    block.type === "resource" &&
    block.resource &&
    typeof block.resource === "object"
  ) {
    const resource = block.resource as Record<string, unknown>;
    return typeof resource.text === "string" ? (
      <pre className="m-0 max-h-80 overflow-auto whitespace-pre-wrap rounded-[var(--fui-radius-md)] border border-[var(--fui-separator)] bg-[var(--fui-code)] p-3.5 font-mono text-xs">
        {resource.text}
      </pre>
    ) : (
      <Json value={resource} />
    );
  }
  if (
    typeof block.data === "string" &&
    block.data.length <= 8_000_000 &&
    typeof block.mimeType === "string"
  ) {
    const src = `data:${block.mimeType};base64,${block.data}`;
    // Only inert raster formats are embedded; remote URLs and SVG are never executed.
    if (
      block.type === "image" &&
      /^image\/(png|jpeg|webp|gif)$/.test(block.mimeType)
    )
      return (
        <picture>
          <img
            src={src}
            alt="Tool result"
            className="max-h-80 max-w-full rounded-[var(--fui-radius-md)] object-contain"
          />
        </picture>
      );
    if (
      block.type === "audio" &&
      /^audio\/(mpeg|mp3|wav|ogg|webm)$/.test(block.mimeType)
    )
      return <audio controls src={src} aria-label="Tool audio result" />;
  }
  return <Json value={value} />;
}

export function ResultView({
  result,
  className,
}: {
  result: unknown;
  className?: string;
}) {
  const [raw, setRaw] = useState(false);
  const object =
    result && typeof result === "object"
      ? (result as Record<string, unknown>)
      : undefined;
  const content = Array.isArray(object?.content)
    ? object.content
    : Array.isArray(object?.contents)
      ? object.contents
      : null;

  return (
    <div className={cn("grid gap-2.5", className)}>
      <div className="flex items-center justify-between gap-2">
        <span className="font-mono text-[11px] text-muted-foreground">
          Result
        </span>
        <Button
          variant="ghost"
          size="xs"
          onClick={() => setRaw(!raw)}
          aria-pressed={raw}
        >
          {raw ? "Preview" : "Raw JSON"}
        </Button>
      </div>
      {raw ? (
        <Json value={result} />
      ) : (
        <>
          {content?.map((block, index) => (
            <Content key={index} value={block} />
          ))}
          {object && "structuredContent" in object ? (
            <Json value={object.structuredContent} />
          ) : (
            !content && <Json value={result} />
          )}
        </>
      )}
    </div>
  );
}

export type JsonSchema =
  | boolean
  | {
      [key: string]: unknown;
      type?: string | string[];
      properties?: Record<string, JsonSchema>;
      required?: string[];
      enum?: unknown[];
      description?: string;
      title?: string;
      items?: JsonSchema;
    };
export interface ToolDefinition {
  name: string;
  title?: string;
  description?: string;
  inputSchema: JsonSchema;
  annotations?: {
    readOnlyHint?: boolean;
    destructiveHint?: boolean;
    untrustedContentHint?: boolean;
    consequentialHint?: boolean;
    [key: string]: unknown;
  };
}
export interface Execution {
  id: string;
  name: string;
  source: "human" | "agent" | "simulator";
  status: "running" | "success" | "error" | "cancelled";
  startedAt: number;
  completedAt?: number;
  args: Record<string, unknown>;
  result?: unknown;
  error?: string;
  progress?: { progress: number; total?: number; message?: string };
}
export type Support = "checking" | "native" | "legacy" | "unsupported";
export interface ToolContext {
  signal: AbortSignal;
  source: Execution["source"];
}
export interface WebTool extends ToolDefinition {
  execute: (
    args: Record<string, unknown>,
    context: ToolContext,
  ) => unknown | Promise<unknown>;
}
export function errorMessage(error: unknown) {
  return error instanceof Error ? error.message : "The operation failed.";
}

"use client";
import { ChevronRight } from "lucide-react";
import { Badge, Button, Progress, StatusDot } from "@fabrials/ui";
import { ResultView } from "@/components/webmcp/result-view";
import type { Execution } from "@/lib/mcp/types";

const statusLabels: Record<string, string> = {
  running: "Running",
  success: "Done",
  error: "Failed",
  cancelled: "Cancelled",
};

const defaultSourceLabels: Record<Execution["source"], string> = {
  human: "You",
  agent: "Agent",
  simulator: "Simulator",
};

export function ExecutionLog({
  executions,
  onCancel,
  onClear,
  sourceLabels = defaultSourceLabels,
}: {
  executions: Execution[];
  onCancel?: (id: string) => void;
  onClear?: () => void;
  /** Who made each call, in the reader's words. */
  sourceLabels?: Partial<Record<Execution["source"], string>>;
}) {
  return (
    <section className="grid gap-3" aria-label="Execution history">
      <header className="flex items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          <h3 className="m-0 text-sm font-medium text-foreground">Activity</h3>
          <Badge size="sm" tone="neutral">
            {executions.length}
          </Badge>
        </div>
        {onClear && (
          <Button
            variant="ghost"
            size="xs"
            disabled={!executions.length}
            onClick={onClear}
          >
            Clear history
          </Button>
        )}
      </header>

      {!executions.length && (
        <div className="flex min-h-24 flex-col items-center justify-center gap-2 rounded-[var(--fui-radius-md)] border border-[var(--fui-separator)] bg-[var(--fui-surface-inset)] px-4 py-6 text-center text-muted-foreground">
          <StatusDot tone="neutral" label="Idle" hideLabel />
          <p className="m-0 text-xs">Run a tool to see its activity here.</p>
        </div>
      )}

      {executions.length > 0 && (
        <div className="grid gap-2">
          {executions.map((e) => {
            const dotTone =
              e.status === "running"
                ? "info"
                : e.status === "success"
                  ? "success"
                  : e.status === "error"
                    ? "danger"
                    : "neutral";
            const statusToneClass =
              e.status === "success"
                ? "text-[var(--fui-success-ink)]"
                : e.status === "error"
                  ? "text-[var(--fui-danger-ink)]"
                  : e.status === "running"
                    ? "text-[var(--brand-ink)]"
                    : "text-muted-foreground";
            return (
              <details
                key={e.id}
                className="group rounded-[var(--fui-radius-md)] border border-[var(--fui-separator)] bg-card transition-colors open:border-border"
                open={e.status === "running" || undefined}
              >
                <summary className="flex cursor-pointer list-none flex-wrap items-center gap-2 px-3 py-2.5 text-xs">
                  <ChevronRight
                    aria-hidden="true"
                    className="size-3.5 text-muted-foreground transition-transform group-open:rotate-90"
                  />
                  <span className="min-w-0 flex-1 truncate font-mono font-medium text-foreground">
                    {e.name}
                  </span>
                  <Badge
                    size="sm"
                    tone={e.source === "agent" ? "info" : "neutral"}
                  >
                    {sourceLabels[e.source] ?? defaultSourceLabels[e.source]}
                  </Badge>
                  <StatusDot
                    tone={dotTone}
                    pulse={e.status === "running"}
                    label={statusLabels[e.status] ?? e.status}
                    role="status"
                    className={`font-mono text-[11px] ${statusToneClass}`}
                  />
                </summary>
                <div className="grid gap-3 border-t border-[var(--fui-separator)] bg-[var(--fui-surface-inset)] p-3">
                  {e.progress && (
                    <div className="grid gap-1.5">
                      <Progress
                        max={100}
                        value={
                          e.progress.total
                            ? (e.progress.progress / e.progress.total) * 100
                            : undefined
                        }
                      />
                      <p
                        role="status"
                        className="m-0 font-mono text-[11px] text-muted-foreground"
                      >
                        {e.progress.message ??
                          `${e.progress.progress} completed`}
                      </p>
                    </div>
                  )}
                  {e.status === "running" && onCancel && (
                    <div>
                      <Button
                        size="xs"
                        variant="outline"
                        onClick={() => onCancel(e.id)}
                      >
                        Cancel request
                      </Button>
                    </div>
                  )}
                  {e.status === "cancelled" && (
                    <p className="m-0 text-xs text-muted-foreground">
                      Request cancelled. Remote effects may have already
                      occurred.
                    </p>
                  )}
                  {e.error && e.status !== "cancelled" && (
                    <p
                      role="alert"
                      className="m-0 text-xs text-[var(--fui-danger-ink)]"
                    >
                      {e.error}
                    </p>
                  )}
                  {e.result !== undefined && <ResultView result={e.result} />}
                  <details className="text-xs">
                    <summary className="cursor-pointer font-mono text-[11px] text-muted-foreground hover:text-foreground">
                      Arguments
                    </summary>
                    <pre className="mt-2 overflow-auto rounded-[var(--fui-radius-sm)] border border-[var(--fui-separator)] bg-[var(--fui-code)] p-3 font-mono text-[11px] leading-relaxed">
                      {JSON.stringify(e.args, null, 2)}
                    </pre>
                  </details>
                </div>
              </details>
            );
          })}
        </div>
      )}
    </section>
  );
}
